<script setup lang="ts">
import { computed, onMounted, onScopeDispose, shallowRef, watch } from 'vue'
import { ElDialog, ElButton } from 'element-plus'
import { readNodeSummaries } from '../../api/nodes'
import { errorMessage, request } from '../../api/client'
import type { BindingPreview, BindingResult, NodeSummary, ProfileView, SourceView } from '../../types/domain'
const props=defineProps<{localNode:NodeSummary}>(),emit=defineEmits<{applied:[result:BindingResult];close:[]}>()
const pool=shallowRef<NodeSummary[]>([]),sources=shallowRef<SourceView[]>([]),profiles=shallowRef<ProfileView[]>([]),selected=shallowRef(''),keyword=shallowRef(''),source=shallowRef(''),page=shallowRef(1),preview=shallowRef<BindingPreview|null>(null),busy=shallowRef(false),error=shallowRef('')
const filtered=computed(()=>pool.value.filter(node=>node.sourceId&&(!source.value||node.sourceId===source.value)&&node.originalName.toLocaleLowerCase().includes(keyword.value.toLocaleLowerCase()))),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/50))),visible=computed(()=>filtered.value.slice((page.value-1)*50,page.value*50))
const sourceNames=computed(()=>new Map(sources.value.map(source=>[source.id,source.name]))),profileNames=computed(()=>new Map(profiles.value.map(profile=>[profile.id,profile.name])))
let sequence=0,read:AbortController|null=null,disposed=false;const lifetime=new AbortController()
watch([keyword,source],()=>{page.value=1});watch(pages,count=>{if(page.value>count)page.value=count});watch(selected,()=>{sequence++;read?.abort();preview.value=null;error.value='';busy.value=false})
onMounted(async()=>{busy.value=true;try{const [nodes,list,documents]=await Promise.all([readNodeSummaries(lifetime.signal),request<SourceView[]>('/sources',{signal:lifetime.signal}),request<ProfileView[]>('/profiles',{signal:lifetime.signal})]);if(!disposed){pool.value=nodes;sources.value=list;profiles.value=documents}}catch(cause){if(!disposed)error.value=errorMessage(cause)}finally{if(!disposed)busy.value=false}})
onScopeDispose(()=>{disposed=true;sequence++;read?.abort();lifetime.abort()})
async function inspect(){if(!selected.value||busy.value)return;const current=++sequence;read?.abort();read=new AbortController();busy.value=true;error.value='';try{const result=await request<BindingPreview>(`/nodes/${props.localNode.id}/binding/preview`,{method:'POST',body:{remoteNodeId:selected.value},signal:read.signal});if(current===sequence&&!disposed)preview.value=result}catch(cause){if(current===sequence&&!disposed)error.value=errorMessage(cause)}finally{if(current===sequence)busy.value=false}}
async function apply(){if(!preview.value||busy.value)return;busy.value=true;error.value='';try{const result=await request<BindingResult>(`/bindings/${preview.value.id}/apply`,{method:'POST',signal:lifetime.signal});if(!disposed)emit('applied',result)}catch(cause){if(!disposed)error.value=errorMessage(cause)}finally{busy.value=false}}
</script>
<template><ElDialog :model-value="true" title="关联本地节点到上游" width="760px" :close-on-click-modal="false" @close="emit('close')"><p><strong>{{ localNode.originalName }}</strong> · {{ localNode.protocol }}</p><p class="muted binding-explanation">仅更新草稿中的引用，现有发布配置继续使用原节点；检查各方案后再主动发布。</p><fieldset :disabled="busy" class="binding-fields"><div class="form-row"><input v-model="keyword" aria-label="筛选关联候选" placeholder="按节点名称筛选…"><select v-model="source" aria-label="关联来源"><option value="">全部上游来源</option><option v-for="item in sources" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="binding-list scroll-area"><label v-for="node in visible" :key="node.id"><input v-model="selected" type="radio" name="binding-node" :value="node.id" :data-remote-node="node.id"><span>{{ node.originalName }}<small>{{ sourceNames.get(node.sourceId!)??'上游订阅' }} · {{ node.protocol }}</small></span></label><p v-if="!visible.length" class="empty-state">没有匹配的上游节点</p></div><div v-if="pages>1" class="toolbar"><span>第 {{ page }} / {{ pages }} 页</span><div class="actions"><button class="text-button" :disabled="page===1" @click="page--">上一页</button><button class="text-button" :disabled="page===pages" @click="page++">下一页</button></div></div></fieldset><div v-if="preview" class="warning binding-explanation"><p>受影响的草稿：{{ preview.affectedProfiles.map(id=>profileNames.get(id)??id.slice(-6)).join('、')||'无' }}</p><p>参数变化：{{ preview.changedFields.join('、')||'连接参数相同' }}</p><p>关联后将跟随上游节点变更；如以后失效，按失效节点规则清理。</p></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="dialog-actions"><ElButton :disabled="busy" @click="emit('close')">取消</ElButton><ElButton :loading="busy" :disabled="!selected" @click="inspect">预览关联影响</ElButton><ElButton type="primary" :disabled="!preview||busy" @click="apply">确认关联到草稿</ElButton></div></ElDialog></template>
<style scoped>.binding-explanation{margin:14px 0;line-height:1.9;font-size:12px}.binding-fields{border:0;padding:0;margin:0;min-width:0}.binding-list{max-height:300px;margin:14px 0}.binding-list label{padding:12px 3px;border-bottom:1px solid var(--line);display:flex;gap:12px;align-items:center}.binding-list small{display:block;color:var(--muted);font-size:10px}</style>
